import json
data = json.load(open('/app/resources/treasury_bulletin_1963_12.json'))

def find_keys(d, target='exchange'):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            if target.lower() in k.lower():
                results.append((k, v))
            results.extend(find_keys(v, target))
    elif isinstance(d, list):
        for item in d:
            results.extend(find_keys(item, target))
    return results

print(find_keys(data, 'exchange'))
"

