import json
data = json.load(open('/app/resources/treasury_bulletin_1963_12.json'))

def find_table(d, target):
    results = []
    if isinstance(d, dict):
        if 'table' in d and target.lower() in str(d.get('table','')).lower():
            results.append(d)
        for k, v in d.items():
            results.extend(find_table(v, target))
    elif isinstance(d, list):
        for item in d:
            results.extend(find_table(item, target))
    return results

tables = find_table(data, 'international financial')
for t in tables[:3]:
    print(json.dumps(t, indent=2)[:1000])
    print('---')
