import json
data = json.load(open('/app/resources/treasury_bulletin_1963_12.json'))
# Explore the structure
def explore(d, depth=0, max_depth=4):
    if depth > max_depth:
        return
    if isinstance(d, dict):
        for k, v in d.items():
            print('  ' * depth + str(k))
            if isinstance(v, (dict, list)) and depth < max_depth:
                explore(v, depth+1, max_depth)
    elif isinstance(d, list) and len(d) > 0 and depth < max_depth:
        print('  ' * depth + f'List[{len(d)}]')
        explore(d[0], depth+1, max_depth)

explore(data['document'])
